import React from 'react';
import { View, Text, StyleSheet } from 'react-native';
import { Ionicons } from '@expo/vector-icons';

const GamificationStats = ({ userStats, calculateXPProgress }) => {
  // Debug logging
  console.log('GamificationStats - userStats:', userStats);
  
  // Handle null/undefined userStats
  if (!userStats) {
    console.log('GamificationStats - userStats is null/undefined');
    return (
      <View style={styles.container}>
        <Text style={styles.levelTitle}>Loading stats...</Text>
      </View>
    );
  }

  // Calculate WoW-style progress
  const xpProgress = calculateXPProgress ? 
    calculateXPProgress(userStats.totalExperience || 0, userStats.level || 1) : 
    { current: 0, required: 100, progress: 0 };

  const getLevelTitle = (level) => {
    const titles = {
      1: "Novice",
      2: "Apprentice",
      3: "Initiate",
      4: "Adept",
      5: "Veteran",
      6: "Expert",
      7: "Master",
      8: "Grandmaster",
      9: "Champion",
      10: "Elite",
      11: "Legend",
      12: "Mythic",
      13: "Divine",
      14: "Transcendent",
      15: "Immortal"
    };
    return titles[level] || `Level ${level}`;
  };

  const getLevelColor = (level) => {
    if (level >= 15) return '#FFD700'; // Gold - Immortal
    if (level >= 12) return '#C0C0C0'; // Silver - Divine
    if (level >= 9) return '#CD7F32'; // Bronze - Champion
    if (level >= 6) return '#8B5CF6'; // Purple - Expert
    if (level >= 3) return '#10B981'; // Green - Adept
    return '#007AFF'; // Blue - Novice
  };

  const getLevelRarity = (level) => {
    if (level >= 15) return 'Immortal';
    if (level >= 12) return 'Divine';
    if (level >= 9) return 'Epic';
    if (level >= 6) return 'Rare';
    if (level >= 3) return 'Uncommon';
    return 'Common';
  };

  return (
    <View style={styles.container}>
      <View style={styles.levelContainer}>
        <View style={[styles.levelBadge, { backgroundColor: getLevelColor(userStats.level || 1) }]}>
          <Text style={styles.levelText}>{userStats.level || 1}</Text>
        </View>
        <View style={styles.levelInfo}>
          <Text style={styles.levelTitle}>{getLevelTitle(userStats.level || 1)}</Text>
          <Text style={styles.rarityText}>{getLevelRarity(userStats.level || 1)}</Text>
          <Text style={styles.experienceText}>
            {userStats.totalExperience || 0} XP • {userStats.totalWorkouts || 0} workouts
          </Text>
        </View>
      </View>
      
      <View style={styles.hoursContainer}>
        <Ionicons name="time" size={16} color="#007AFF" />
        <Text style={styles.hoursText}>{Math.round((userStats.totalDuration || 0) / 60)} hours</Text>
      </View>

      <View style={styles.progressContainer}>
        <View style={styles.progressBar}>
          <View 
            style={[
              styles.progressFill, 
              { width: `${xpProgress.progress * 100}%` }
            ]} 
          />
        </View>
        <Text style={styles.progressText}>
          {xpProgress.current}/{xpProgress.required} XP to next level
        </Text>
      </View>

      {/* Achievement and Quest Summary */}
      {(userStats.achievements?.length > 0 || userStats.activeQuests?.length > 0) && (
        <View style={styles.achievementSection}>
          <Text style={styles.sectionTitle}>Recent Achievements</Text>
          <View style={styles.achievementRow}>
            <Ionicons name="star" size={16} color="#FFD700" />
            <Text style={styles.achievementText}>
              {userStats.achievements?.length || 0} achievements unlocked
            </Text>
          </View>
          {userStats.activeQuests?.length > 0 && (
            <View style={styles.achievementRow}>
              <Ionicons name="bookmark" size={16} color="#10B981" />
              <Text style={styles.achievementText}>
                {userStats.activeQuests.length} active quests
              </Text>
            </View>
          )}
        </View>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    backgroundColor: '#fff',
    padding: 20,
    borderRadius: 12,
    marginHorizontal: 20,
    marginVertical: 10,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  levelContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 15,
  },
  levelBadge: {
    width: 50,
    height: 50,
    borderRadius: 25,
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 15,
  },
  levelText: {
    fontSize: 20,
    fontWeight: 'bold',
    color: '#fff',
  },
  levelInfo: {
    flex: 1,
  },
  levelTitle: {
    fontSize: 18,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 2,
  },
  rarityText: {
    fontSize: 12,
    color: '#666',
    fontStyle: 'italic',
    marginBottom: 2,
  },
  experienceText: {
    fontSize: 14,
    color: '#666',
  },
  progressContainer: {
    marginBottom: 15,
  },
  progressBar: {
    height: 8,
    backgroundColor: '#f0f0f0',
    borderRadius: 4,
    marginBottom: 8,
  },
  progressFill: {
    height: '100%',
    backgroundColor: '#007AFF',
    borderRadius: 4,
  },
  progressText: {
    fontSize: 12,
    color: '#666',
    textAlign: 'center',
  },
  statsRow: {
    flexDirection: 'row',
    justifyContent: 'space-around',
    marginBottom: 15,
  },
  statItem: {
    alignItems: 'center',
  },
  statValue: {
    fontSize: 18,
    fontWeight: 'bold',
    color: '#333',
    marginTop: 4,
  },
  statLabel: {
    fontSize: 12,
    color: '#666',
    marginTop: 2,
  },
  achievementSection: {
    borderTopWidth: 1,
    borderTopColor: '#f0f0f0',
    paddingTop: 15,
  },
  sectionTitle: {
    fontSize: 14,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 8,
  },
  achievementRow: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 4,
  },
  achievementText: {
    fontSize: 12,
    color: '#666',
    marginLeft: 6,
  },
});

export default GamificationStats;
